  ('duo-cherry-blossom-samurai', 'cherry-blossom-samurai-duo', 'Cherry Blossom Samurai (Matching Duo)', 'Delicate yet lethal: the Sakura Swordsman with bamboo hat and the Blossom Kunoichi surrounded by swirling cherry blossoms. Sold together as one matching pair.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 101, 2, NULL, NULL, NULL, NULL, 'common', 'S01', '{"duo":{"partA":"Sakura Swordsman","partB":"Blossom Kunoichi","pairing":"complementary","pairNote":"Two companion samurai warriors surrounded by falling cherry blossom petals."},"shortDescription":"Serene sakura swordsmen amidst fluttering spring petals."}'::jsonb),
  ('duo-oni-masks', 'oni-masks-duo', 'Twin Oni Masks (Matching Duo)', 'Traditional Japanese folklore demon masks: fierce red Aka-Oni with golden horns and menacing blue Ao-Oni with silver lightning aura. Sold together as a matching duo.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 102, 2, NULL, NULL, NULL, NULL, 'uncommon', 'S01', '{"duo":{"partA":"Crimson Aka-Oni Mask","partB":"Azure Ao-Oni Mask","pairing":"complementary","pairNote":"Complementary red and blue oni masks that balance fierce guardian energy."},"shortDescription":"Legendary Crimson Aka-Oni and Azure Ao-Oni guardian masks."}'::jsonb),
  ('duo-shadow-sorcerer', 'shadow-sorcerers-duo', 'Shadow Sorcerers (Matching Duo)', 'Mystic dark fantasy pair: Void Summoner weaving shadow tendrils and Eclipse Sorceress channeling violet spirit flames. Perfect for Jujutsu and anime magic fans.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 103, 2, NULL, NULL, NULL, NULL, 'uncommon', 'S01', '{"duo":{"partA":"Void Summoner","partB":"Eclipse Sorceress","pairing":"complementary","pairNote":"Twin shadow practitioners wielding complementary cursed flame arts."},"shortDescription":"Dark occult sorcery and purple cursed flames."}'::jsonb),
  ('duo-flame-lightning-ninjas', 'flame-and-lightning-ninjas-duo', 'Flame & Lightning Ninjas (Matching Duo)', 'Blazing Fire Shinobi with incandescent flame daggers paired with Chidori Lightning Shinobi crackling with blue electricity kunai. Sold together as one matching duo.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 104, 2, NULL, NULL, NULL, NULL, 'rare', 'S01', '{"duo":{"partA":"Blazing Fire Shinobi","partB":"Chidori Lightning Shinobi","pairing":"complementary","pairNote":"Opposing elemental jutsu warriors designed to mirror each other on your devices."},"shortDescription":"Rival elemental shinobi crackling with fire and thunder."}'::jsonb),
  ('duo-tactical-fighters', 'tactical-fighters-duo', 'Tactical Spec-Ops Fighters (Matching Duo)', 'Two elite tactical operatives: Spec-Ops Ghost with night-vision optics and Cyber Recon Sniper with silenced loadout. A prime matching duo for tactical gaming fans.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 105, 2, NULL, NULL, NULL, NULL, 'common', 'S01', '{"duo":{"partA":"Spec-Ops Ghost Operative","partB":"Cyber Recon Sniper","pairing":"complementary","pairNote":"Coordinated squad members watching each other’s six in high-stakes operations."},"shortDescription":"Cyber tactical ghost operatives equipped for urban stealth."}'::jsonb),
  ('duo-elemental-dragons', 'elemental-dragons-duo', 'Celestial Elemental Dragons (Matching Duo)', 'Breathtaking Eastern mythical dragons: Celestial Solar Dragon glowing with golden sun rays and Abyssal Lunar Dragon coiling under the crescent moon.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 106, 2, NULL, NULL, NULL, NULL, 'rare', 'S01', '{"duo":{"partA":"Celestial Solar Dragon","partB":"Abyssal Lunar Dragon","pairing":"complementary","pairNote":"Sun and moon serpentine dragons that create a cosmic circular harmony."},"shortDescription":"Serpentine Solar and Lunar dragons circling the heavens."}'::jsonb),
  ('duo-water-blossom-warriors', 'water-blossom-warriors-duo', 'Water Blossom Warriors (Matching Duo)', 'Dynamic swordsmanship stickers inspired by water breathing forms: Tidal Blade Swordsman slicing surging waves and Lotus Flow Swordswoman dancing with floral ripples.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 107, 2, NULL, NULL, NULL, NULL, 'uncommon', 'S01', '{"duo":{"partA":"Tidal Blade Swordsman","partB":"Lotus Flow Swordswoman","pairing":"complementary","pairNote":"Fluid water techniques that connect seamlessly when displayed together."},"shortDescription":"Flowing water breathing swordsmanship and lotus petals."}'::jsonb),
  ('duo-fire-ice-dragons', 'fire-and-ice-dragons-duo', 'Fire & Ice Dragons (Matching Duo)', 'Two legendary fantasy wyverns: Inferno Dragon radiating volcanic heat and Frostbite Dragon enveloped in frozen glacial spikes. Sold together as a matching pair.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 108, 2, NULL, NULL, NULL, NULL, 'rare', 'S01', '{"duo":{"partA":"Inferno Dragon","partB":"Frostbite Dragon","pairing":"complementary","pairNote":"Elemental opposites: pure fire meets sub-zero ice in high-detail die-cut vinyl."},"shortDescription":"Molten magma dragon paired with glacial frostbite dragon."}'::jsonb),
  ('duo-shadow-ninjas', 'shadow-ninjas-duo', 'Shadow Ninjas (Matching Duo)', 'Stealth shinobi duo: Midnight Katana Shinobi drawing his blade mid-leap and Shuriken Smoke Shinobi disappearing into smoke bombs.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 109, 2, NULL, NULL, NULL, NULL, 'common', 'S01', '{"duo":{"partA":"Midnight Katana Shinobi","partB":"Shuriken Smoke Shinobi","pairing":"two-poses","pairNote":"Two action poses of covert shinobi executing a synchronized night raid."},"shortDescription":"Midnight katana shinobi leaping through smoke and darkness."}'::jsonb),
  ('duo-sun-moon', 'celestial-sun-and-moon-duo', 'Celestial Sun & Moon (Matching Duo)', 'Golden radiant sun with celestial rays paired with a serene crescent moon face surrounded by stars. The timeless harmony of day and night.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 110, 2, NULL, NULL, NULL, NULL, 'common', 'S01', '{"duo":{"partA":"Golden Radiant Sun","partB":"Silver Crescent Moon","pairing":"complementary","pairNote":"Day and night harmony: share the sun and moon with someone in your universe."},"shortDescription":"Boho radiant sun and dreamy silver crescent moon."}'::jsonb),
  ('duo-astronauts', 'astronauts-in-space-duo', 'Astronauts in Space (Matching Duo)', 'Romantic cosmic adventure: Floating Spacewalker reaching out his gloved hand and Star-Tethered Explorer floating back to meet his grasp across zero gravity.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 111, 2, NULL, NULL, NULL, NULL, 'uncommon', 'S01', '{"duo":{"partA":"Floating Spacewalker","partB":"Star-Tethered Explorer","pairing":"complementary","pairNote":"Two astronauts reaching across the vastness of space to stay connected."},"shortDescription":"Two cosmic spacewalkers reaching across the starlight."}'::jsonb),
  ('duo-crystal-heart', 'crystal-heart-halves-duo', 'Crystal Heart Halves (Matching Duo)', 'A sparkling rose quartz crystal heart split cleanly down the center. Keep one half and give the other away — the crystal only sparkles whole when both are together.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 112, 2, NULL, NULL, NULL, NULL, 'common', 'S01', '{"duo":{"partA":"Left Crystal Facet","partB":"Right Crystal Facet","pairing":"halves","pairNote":"Two halves of one faceted crystal heart illustration. One for you, one for your person."},"shortDescription":"Rose quartz gemstone heart split into two interlocking halves."}'::jsonb),
  ('duo-paper-airplane-love-note', 'paper-airplane-love-note-duo', 'Paper Airplane & Love Note (Matching Duo)', 'Whimsical romantic pair: a folded love letter with red wax heart seal and a crisp paper airplane flying through the clouds leaving a dotted heart trail.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 113, 2, NULL, NULL, NULL, NULL, 'common', 'S01', '{"duo":{"partA":"Sealed Love Letter","partB":"Gliding Paper Airplane","pairing":"complementary","pairNote":"A heartfelt letter sent, and the paper plane carrying it across the distance."},"shortDescription":"A sealed vintage love letter and a gliding paper plane."}'::jsonb),
  ('duo-shared-umbrella-in-rain', 'shared-umbrella-in-rain-duo', 'Shared Umbrella in the Rain (Matching Duo)', 'Cozy rainy day warmth: rain boots splashing happily in ripples and a cheerful yellow umbrella keeping two people dry and safe from the storm.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 114, 2, NULL, NULL, NULL, NULL, 'common', 'S01', '{"duo":{"partA":"Rain Boots in Puddle","partB":"Yellow Umbrella Shelter","pairing":"complementary","pairNote":"Staying warm and sheltered together even on the rainiest afternoon."},"shortDescription":"Rain boots splashing in puddles under a shared bright umbrella."}'::jsonb),
  ('duo-spaghetti-pets', 'spaghetti-pets-duo', 'Spaghetti Pets (Matching Duo)', 'Heart-melting pet pair inspired by classic cinematic romance: an eager golden puppy slurping one end of a spaghetti strand and a sweet calico kitten meeting at the other.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 115, 2, NULL, NULL, NULL, NULL, 'common', 'S01', '{"duo":{"partA":"Spaghetti Puppy","partB":"Spaghetti Kitten","pairing":"complementary","pairNote":"Two adorable pets sharing one long pasta noodle until their noses touch."},"shortDescription":"Fluffy puppy and cute kitten sharing a pasta strand."}'::jsonb),
  ('duo-magnetic-hearts', 'magnetic-hearts-duo', 'Magnetic Hearts (Matching Duo)', 'Opposites attract: vibrant red North Pole magnetic heart and cool blue South Pole magnetic heart throwing electric magnetic sparks toward each other.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 116, 2, NULL, NULL, NULL, NULL, 'common', 'S01', '{"duo":{"partA":"North Pole Heart (Red)","partB":"South Pole Heart (Blue)","pairing":"complementary","pairNote":"Physical law of attraction: no matter where you place them, they pull together."},"shortDescription":"North and South pole hearts attracted by irresistible magnetism."}'::jsonb),
  ('duo-lock-and-vintage-key', 'lock-and-vintage-key-duo', 'Heart Lock & Vintage Key (Matching Duo)', 'A timeless symbol of trust and devotion: an embossed brass heart padlock and an ornate vintage skeleton key designed precisely to unlock it.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 117, 2, NULL, NULL, NULL, NULL, 'common', 'S01', '{"duo":{"partA":"Antique Heart Padlock","partB":"Filigree Skeleton Key","pairing":"complementary","pairNote":"The lock and the only key in the world that turns it."},"shortDescription":"Ornate antique heart padlock and its matching filigree key."}'::jsonb),
  ('duo-campfire-marshmallow', 'campfire-and-marshmallow-duo', 'Campfire & Marshmallow (Matching Duo)', 'Nostalgic outdoor adventure vibes: glowing campfire logs crackling with embers and a fluffy golden-brown marshmallow roasted on a birch stick.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 118, 2, NULL, NULL, NULL, NULL, 'common', 'S01', '{"duo":{"partA":"Crackling Campfire","partB":"Toasted Marshmallow Skewer","pairing":"complementary","pairNote":"The flame and the treat: best friends around the evening fire."},"shortDescription":"A crackling woodland campfire and a toasted golden marshmallow."}'::jsonb),
  ('duo-walkie-talkie', 'walkie-talkies-over-and-out-duo', 'Walkie-Talkies: Over & Out (Matching Duo)', 'Retro 80s adventure comms: Teal radio transmitting "Do you copy?" and Coral radio replying "Loud and clear, over and out!". Perfect for retro sci-fi & Stranger Things fans.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 119, 2, NULL, NULL, NULL, NULL, 'uncommon', 'S01', '{"duo":{"partA":"Walkie-Talkie: Do You Copy?","partB":"Walkie-Talkie: Over & Out","pairing":"complementary","pairNote":"Direct secret channel between two best friends or partners in adventure."},"shortDescription":"Retro 80s handheld walkie-talkies with speech waveforms."}'::jsonb),
  ('duo-origami-cranes', 'origami-cranes-duo', 'Origami Cranes (Matching Duo)', 'Japanese paper craft elegance: soft blush pink origami crane paired with a calm mint green crane, both accented with subtle gold foil edges.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 120, 2, NULL, NULL, NULL, NULL, 'common', 'S01', '{"duo":{"partA":"Blush Origami Crane","partB":"Mint Origami Crane","pairing":"complementary","pairNote":"A thousand wishes in flight: peaceful origami companions for laptops and journals."},"shortDescription":"Delicate pastel blush and mint folded paper cranes in flight."}'::jsonb),
  ('duo-love-potions', 'love-potions-duo', 'Magic Love Potions (Matching Duo)', 'Whimsical alchemy glassware: heart-shaped Elixir of Amour flask bubbling with pink fumes and star-shaped Potion of Eternity glowing with starry lavender mist.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 121, 2, NULL, NULL, NULL, NULL, 'uncommon', 'S01', '{"duo":{"partA":"Elixir of Amour Flask","partB":"Potion of Eternity Flask","pairing":"complementary","pairNote":"Two brewed alchemical concoctions of romance and magic."},"shortDescription":"Enchanted glass elixir bottles sparkling with magical mist."}'::jsonb),
  ('duo-kissing-koi', 'kissing-koi-fish-duo', 'Yin-Yang Kissing Koi (Matching Duo)', 'Fluid aquatic harmony: a vibrant crimson & white Kohaku koi swimming clockwise and a sleek midnight black Karashi koi completing the sacred circle of balance.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 122, 2, NULL, NULL, NULL, NULL, 'rare', 'S01', '{"duo":{"partA":"Ruby Kohaku Koi","partB":"Ink Black Karashi Koi","pairing":"halves","pairNote":"Two swimming koi that together form a complete yin-yang circle of balance."},"shortDescription":"Graceful Japanese Kohaku and Karashi carp forming a yin-yang circle."}'::jsonb),
  ('duo-red-string-hands', 'red-string-of-fate-duo', 'Red String of Fate (Matching Duo)', 'Poignant East Asian legend: Left hand pinky reaching forward bound by a red string, and the matching Right hand pinky holding the other end of an unbreakable bond.', 39, TRUE, 'PUBLISHED', 'duo', 'stickers', FALSE, FALSE, 123, 2, NULL, NULL, NULL, NULL, 'rare', 'S01', '{"duo":{"partA":"Left Pinky with Red String","partB":"Right Pinky with Red String","pairing":"halves","pairNote":"The red string of fate that connects two people destined to meet, regardless of time or distance."},"shortDescription":"Hands connected by the unbroken crimson thread of destiny."}'::jsonb),
